'use strict';

// MODULES //

var isLayout = require( '@stdlib/blas/base/assert/is-layout' );
var isColumnMajor = require( '@stdlib/ndarray/base/assert/is-column-major-string' );
var reinterpret = require( '@stdlib/strided/base/reinterpret-complex128' );
var max = require( '@stdlib/math/base/special/fast/max' );
var resolveOrder = require( '@stdlib/blas/base/layout-resolve-enum' );
var format = require( '@stdlib/string/format' );
var addon = require( './../src/addon.node' );


// MAIN //

/**
* Computes the Cartesian square for a double-precision complex floating-point strided array.
*
* @param {string} order - storage layout
* @param {NonNegativeInteger} N - number of indexed elements
* @param {Complex128Array} x - input array
* @param {integer} strideX - stride length for `x`
* @param {Complex128Array} out - output array
* @param {integer} LDO - stride length between successive contiguous vectors of the matrix `out` (a.k.a., leading dimension of `out`)
* @throws {TypeError} first argument must be a valid order
* @throws {RangeError} sixth argument must be a valid stride length
* @returns {Complex128Array} output array
*
* @example
* var Complex128Array = require( '@stdlib/array/complex128' );
*
* var x = new Complex128Array( [ 1.0, 2.0, 3.0, 4.0 ] );
* var out = new Complex128Array( 8 );
*
* zcartesianSquare( 'row-major', x.length, x, 1, out, 2 );
* // out => <Complex128Array>[ 1.0, 2.0, 1.0, 2.0, 1.0, 2.0, 3.0, 4.0, 3.0, 4.0, 1.0, 2.0, 3.0, 4.0, 3.0, 4.0 ]
*/
function zcartesianSquare( order, N, x, strideX, out, LDO ) {
	var viewX;
	var viewO;

	if ( !isLayout( order ) ) {
		throw new TypeError( format( 'invalid argument. First argument must be a valid order. Value: `%s`.', order ) );
	}
	if ( isColumnMajor( order ) ) {
		if ( LDO < max( 1, N*N ) ) {
			throw new RangeError( format( 'invalid argument. Sixth argument must be greater than or equal to max(1,%d). Value: `%d`.', N*N, LDO ) );
		}
	} else if ( LDO < 2 ) { // row-major
		throw new RangeError( format( 'invalid argument. Sixth argument must be greater than or equal to max(1,%d). Value: `%d`.', 2, LDO ) );
	}
	viewX = reinterpret( x, 0 );
	viewO = reinterpret( out, 0 );
	addon( resolveOrder( order ), N, viewX, strideX, viewO, LDO );
	return out;
}


// EXPORTS //

module.exports = zcartesianSquare;
